class PackedMemoContractTest {

	@Test
	void baseAndOverlayInsertionAreIdempotentWithPermanentGroups() {
		PackedQuery query = query();
		PackedMemo memo = memo(query);
		int rootExpressionId = query.rootRelId();
		int rootGroupId = memo.logicalGroupId(rootExpressionId);
		int[] children = { query.relChild(rootExpressionId, 0), query.relChild(rootExpressionId, 1) };
		int initialExpressionCount = memo.logicalExpressionCount();
		int initialGroupCount = memo.groupCount();

		int repeated = memo.addLogicalAlternative(rootGroupId, PackedRelOp.JOIN, 0, 0, 0, children, 0, 2);
		assertEquals(rootExpressionId, repeated);
		assertEquals(initialExpressionCount, memo.logicalExpressionCount());
		assertEquals(initialGroupCount, memo.groupCount());

		// Rediscovering an expression that is already canonicalized in another group is a group-merge the
		// append-only memo cannot represent: the alternative is dropped (0) without mutating the memo.
		assertEquals(0, memo.addLogicalAlternative(children[0], PackedRelOp.JOIN, 0, 0, 0, children, 0, 2));
		assertEquals(initialExpressionCount, memo.logicalExpressionCount());
		assertEquals(initialGroupCount, memo.groupCount());

		int helper = memo.addCanonicalLogical(99, 17, 2, 3, new int[] { rootGroupId }, 0, 1);
		int helperGroup = memo.logicalGroupId(helper);
		assertEquals(helper, memo.addCanonicalLogical(99, 17, 2, 3, new int[] { rootGroupId }, 0, 1));
		assertEquals(initialExpressionCount + 1, memo.logicalExpressionCount());
		assertEquals(initialGroupCount + 1, memo.groupCount());
		assertEquals(initialGroupCount + 1, helperGroup);
	}

	@Test
	void logicalPhysicalAndWinnerIdentitiesRemainSeparate() {
		PackedQuery query = query();
		PackedMemo memo = memo(query);
		int rootExpressionId = query.rootRelId();
		int rootGroupId = memo.logicalGroupId(rootExpressionId);
		int[] children = new int[0];
		int anyPropertyId = memo.anyPropertyId();
		int accessPathPropertyId = memo.internProperty(0, 0, 77, 0, 0, 0, 0, 0, 0, 0, 0, 0);

		int physical = memo.addPhysicalAlternative(rootGroupId, 200, 31, anyPropertyId, 5, children, 0, 0);
		assertEquals(physical,
				memo.addPhysicalAlternative(rootGroupId, 200, 31, anyPropertyId, 5, children, 0, 0));
		assertNotEquals(physical,
				memo.addPhysicalAlternative(rootGroupId, 200, 31, accessPathPropertyId, 5, children, 0, 0));
		assertNotEquals(physical,
				memo.addPhysicalAlternative(rootGroupId, 200, 31, anyPropertyId, 6, children, 0, 0));
		assertEquals(3, memo.physicalExpressionCount());

		int[] noChildWinners = new int[0];
		int anyWinner = memo.offerWinner(rootGroupId, anyPropertyId, 0, 0, 0, physical, 2.0d, 20.0d,
				20.0d, noChildWinners, 0, 0);
		int accessPathWinner = memo.offerWinner(rootGroupId, accessPathPropertyId, 0, 0, 0, physical, 2.0d,
				20.0d, 20.0d, noChildWinners, 0, 0);
		assertNotEquals(anyWinner, accessPathWinner);
		int replacementWinner = memo.offerWinner(rootGroupId, anyPropertyId, 0, 0, 0, physical, 1.0d, 10.0d,
				10.0d, noChildWinners, 0, 0);
		assertNotEquals(anyWinner, replacementWinner);
		assertEquals(replacementWinner, memo.findWinner(rootGroupId, anyPropertyId, 0, 0, 0));
		assertEquals(20.0d, memo.winnerTotalCost(anyWinner));
		assertEquals(10.0d, memo.winnerTotalCost(replacementWinner));
		assertEquals(3, memo.winnerCount());
		assertEquals(physical, memo.winnerPhysicalExpressionId(replacementWinner));
	}

	@Test
	void evidenceContextDistinguishesTheInputCostingEvent() {
		PackedQuery query = query();
		PackedMemo memo = memo(query);
		int relationId = query.relChild(query.rootRelId(), 0);
		int[] relations = { relationId };
		double[] contributions = { 3.0d };

		int withoutEvent = memo.internEvidenceContext(relations, contributions, 0, 1, 3.0d, 7, 0, 0, 0);
		int explicitZeroEvent = memo.internEvidenceContext(relations, contributions, 0, 1, 3.0d, 7, 0, 0, 0, 0);
		int firstEvent = memo.internEvidenceContext(relations, contributions, 0, 1, 3.0d, 7, 0, 0, 0, 11);
		int secondEvent = memo.internEvidenceContext(relations, contributions, 0, 1, 3.0d, 7, 0, 0, 0, 12);

		assertEquals(withoutEvent, explicitZeroEvent);
		assertNotEquals(withoutEvent, firstEvent);
		assertNotEquals(firstEvent, secondEvent);
		assertEquals(firstEvent,
				memo.internEvidenceContext(relations, contributions, 0, 1, 3.0d, 7, 0, 0, 0, 11));
	}

	@Test
	void decisionDraftCollapsesRepeatedImmutableEventsButRetainsDistinctAlternatives() {
		PackedQuery query = query();
		PackedMemo memo = memo(query);
		int rootGroupId = memo.logicalGroupId(query.rootRelId());
		int anyPropertyId = memo.anyPropertyId();
		int[] noChildren = new int[0];
		int physical = memo.addPhysicalAlternative(rootGroupId, PackedRelOp.JOIN, 0, anyPropertyId, 7,
				noChildren, 0, 0);
		int alternativePhysical = memo.addPhysicalAlternative(rootGroupId, PackedRelOp.JOIN, 0, anyPropertyId, 8,
				noChildren, 0, 0);

		PackedCostEstimate firstEvent = event(11, 7, 10.0d);
		int firstMetadata = memo.addPhysicalMetadata(firstEvent, 10.0d, 10.0d);
		int rootWinner = memo.offerWinnerWithMetadata(rootGroupId, anyPropertyId, 0, 0, 0, physical,
				firstMetadata, 10.0d, 10.0d, 10.0d, noChildren, 0, 0);
		int repeatedMetadata = memo.addPhysicalMetadata(event(11, 7, 10.0d), 10.0d, 10.0d);
		memo.offerWinnerWithMetadata(rootGroupId, anyPropertyId, 0, 0, 0, physical, repeatedMetadata,
				10.0d, 10.0d, 10.0d, noChildren, 0, 0);
		int alternativeMetadata = memo.addPhysicalMetadata(event(12, 8, 20.0d), 20.0d, 20.0d);
		memo.offerWinnerWithMetadata(rootGroupId, anyPropertyId, 0, 0, 0, alternativePhysical,
				alternativeMetadata, 20.0d, 20.0d, 20.0d, noChildren, 0, 0);

		PackedMemo.PackedDecisionDraft draft = memo.decisionDraft(rootWinner);

		assertArrayEquals(new int[] { 11, 12 }, draft.candidateEventIds(),
				"one immutable candidate event belongs in the certificate once");
		assertArrayEquals(new byte[] { 1, 0 }, draft.outcomes(),
				"deduplication must retain the original accepted comparison outcome");
	}

	@Test
	void decisionTraceNeverConflatesContextFrontierOrChildEvidence() {
		PackedDecisionTraceArena trace = new PackedDecisionTraceArena();
		PackedPhysicalMetadataArena metadata = new PackedPhysicalMetadataArena(8);
		PackedWinnerTable winners = new PackedWinnerTable(4, 4, 4, 1);
		int[] noChildren = new int[0];
		int rootMetadata = metadata.append(event(31, 4, 10.0d), 10.0d, 10.0d);
		int distinctStateMetadata = metadata.append(event(31, 5, 10.0d), 10.0d, 10.0d);
		int firstChildMetadata = metadata.append(event(41, 6, 2.0d), 2.0d, 2.0d);
		int secondChildMetadata = metadata.append(event(42, 7, 2.0d), 2.0d, 2.0d);
		int firstChild = winners.offerWithMetadata(1, 1, 0, 0, 0, 101, firstChildMetadata, 2.0d, 2.0d,
				2.0d, noChildren, 0, 0);
		int secondChild = winners.offerWithMetadata(2, 1, 0, 0, 0, 102, secondChildMetadata, 2.0d, 2.0d,
				2.0d, noChildren, 0, 0);
		int[] firstChildCandidate = { firstChild };
		int[] secondChildCandidate = { secondChild };

		appendDecision(trace, winners, metadata, 0, rootMetadata, noChildren, false);
		appendDecision(trace, winners, metadata, 0, rootMetadata, noChildren, true);
		appendDecision(trace, winners, metadata, 1, rootMetadata, noChildren, false);
		appendDecision(trace, winners, metadata, 0, distinctStateMetadata, noChildren, false);
		appendDecision(trace, winners, metadata, 0, rootMetadata, firstChildCandidate, false);
		appendDecision(trace, winners, metadata, 0, rootMetadata, secondChildCandidate, false);

		assertEquals(5, trace.size());
		assertTrue(trace.accepted(0), "a later identical accepted offer must update the retained outcome");
	}

	@Test
	void memoSurfaceHasNoGroupMergeOrRenameOperation() {
		for (Method method : PackedMemo.class.getDeclaredMethods()) {
			String name = method.getName().toLowerCase();
			assertFalse(name.contains("merge") || name.contains("alias") || name.contains("rename")
					|| name.contains("rehash"), name);
		}
	}

	private static PackedMemo memo(PackedQuery query) {
		return new PackedMemo(query, 130, 16, 16, 16, 16, 32);
	}

	private static PackedCostEstimate event(int eventId, int evidenceStateId, double cost) {
		PackedCostEstimate estimate = new PackedCostEstimate();
		estimate.setRows(cost, cost);
		estimate.setCostEventId(eventId);
		estimate.setEvidenceStateId(evidenceStateId);
		return estimate;
	}

	private static void appendDecision(PackedDecisionTraceArena trace, PackedWinnerTable winners,
			PackedPhysicalMetadataArena metadata, int inputContextId, int metadataId, int[] children,
			boolean accepted) {
		trace.append(3, 1, 0, inputContextId, 0, 201, metadataId, PackedWinnerTable.COSTED, 0, 1.0d,
				10.0d, 10.0d, accepted, winners, metadata, children, 0, children.length);
	}

	private static PackedQuery query() {
		SimpleValueFactory valueFactory = SimpleValueFactory.getInstance();
		StatementPattern left = new StatementPattern(Var.of("person"),
				Var.of("namePredicate", valueFactory.createIRI("urn:name")), Var.of("name"));
		StatementPattern right = new StatementPattern(Var.of("person"),
				Var.of("agePredicate", valueFactory.createIRI("urn:age")), Var.of("age"));
		return PackedQueryCodec.encode(new Join(left, right));
	}
}
